    public static function line(string $name, int $size = 18): string
    {
        $inner = self::LINE[$name] ?? self::LINE['server'];

        return '<svg xmlns="http://www.w3.org/2000/svg" width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $inner . '</svg>';
    }

    public static function brand(string $slug, int $size = 18): string
    {
        $d = self::BRAND[$slug] ?? null;
        if ($d === null) {
            return self::line('server', $size);
        }

        return '<svg xmlns="http://www.w3.org/2000/svg" width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="' . $d . '"/></svg>';
    }

    /** "brand:redis" or "line:cpu" → svg. */
    public static function render(string $ref, int $size = 18): string
    {
        [$kind, $name] = array_pad(explode(':', $ref, 2), 2, '');

        return $kind === 'brand' ? self::brand($name, $size) : self::line($name, $size);
    }
